mapper.select:
SELECT g.*, s.name AS supplier_name FROM goods g LEFT JOIN supplier s ON g.supplier_id = s.id WHERE g.is_deleted = 0
AND g.name LIKE CONCAT('%', #{name}, '%')
AND g.supplier_id = #{supplierId}
ORDER BY g.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM goods WHERE is_deleted = 0
AND name LIKE CONCAT('%', #{name}, '%')
AND supplier_id = #{supplierId}

SELECT COUNT(*) FROM purchase_detail pd
JOIN purchase_main pm ON pd.purchase_main_id = pm.id
WHERE pd.goods_id = #{goodsId}
